-- Build Mortgage Broking Administration Australia.
insert into public.training_courses (slug,title,summary,category,country_focus,estimated_minutes,recommended_order,status,content_version,trademark_disclaimer,reviewed_by,last_reviewed_at,published_at,created_at,updated_at)
values ('mortgage-broking-administration-australia','Mortgage Broking Administration Australia','Australian mortgage-broking administration training for Filipino VAs covering client intake, sensitive documents, fact-find data entry, lender research support, application packaging, lender conditions, settlement, CRM, recordkeeping, and credit-advice boundaries.','industry','Australia',240,26,'draft',1,'This independent course is administrative training only. It does not authorize the learner to provide credit assistance, mortgage broking, lender or product recommendations, responsible-lending assessments, or financial advice. Australian credit activities may require licensing, authorisation, training, supervision, and compliance under the National Credit Act and ASIC guidance.',null,null,null,now(),now())
