insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='mortgage-broking-administration-australia'),'Broker Role and Client Intake','Understand licensing, privacy, and safe file setup.',1) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=1),'australian-mortgage-broking-model-licensing-and-va-boundaries','Australian Mortgage Broking Model, Licensing, and VA Boundaries','Mortgage brokers help consumers understand needs and goals, consider loan options, apply for credit, and manage the process through settlement. Australian credit activity is regulated, so a VA must be very clear about the difference between administration and providing credit assistance or advice.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand the mortgage-broking workflow","Recognize licensing and representative boundaries","Define safe VA administration tasks"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Mortgage brokers help consumers understand needs and goals, consider loan options, apply for credit, and manage the process through settlement. Australian credit activity is regulated, so a VA must be very clear about the difference between administration and providing credit assistance or advice."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Mortgage brokers may operate under an Australian credit licence or as representatives of a licensee.","ASIC maintains credit-licensing and representative registers.","Mortgage brokers have best-interests obligations when providing credit assistance.","Credit representatives providing third-party home-loan credit assistance have training and competency requirements.","A VA can support document collection, CRM, status tracking, appointments, data entry, and lender follow-up without recommending a loan."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the broker, licensee or representative structure.","Confirm the VA''s documented role.","Map the client journey from enquiry to settlement.","Identify which conversations are credit assistance or advice and who is authorized to conduct them.","Learn the broker''s disclosure, recordkeeping, privacy, and escalation process.","Use approved scripts that avoid product recommendations."]},{"type":"callout","title":"Stay inside the role","text":"Do not recommend lenders or loan products, assess suitability, tell a consumer what they can afford, give credit advice, interpret responsible-lending obligations, or hold yourself out as a mortgage broker or credit representative unless appropriately authorized and qualified."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling yourself a broker because you work for one","Suggesting a lender from personal experience","Answering product-suitability questions","Using broker credentials to perform regulated steps","Treating compliance forms as optional admin"]},{"type":"scenario","title":"Practice scenario","text":"A client asks, ''Which lender do you think is best for me?'' Explain the VA response and handoff to the broker."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Know the licence and role structure.","Keep credit assistance with authorized brokers.","Use approved scripts.","Document handoffs."]}]'::jsonb,30,1,false,1,null,null,now(),now())
