insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=1),'client-enquiry-identity-privacy-and-document-intake','Client Enquiry, Identity, Privacy, and Document Intake','Mortgage applications involve identity, income, employment, bank statements, liabilities, expenses, assets, property details, and other highly sensitive financial information. Strong intake protects the consumer and the brokerage.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Collect documents using approved checklists","Protect sensitive financial information","Track missing items without interpreting them"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Mortgage applications involve identity, income, employment, bank statements, liabilities, expenses, assets, property details, and other highly sensitive financial information. Strong intake protects the consumer and the brokerage."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Financial data and identity documents are highly sensitive.","The broker''s fact-find and responsible-lending process determines what information is required.","Document freshness and completeness matter.","A VA may check that a document is present and readable without deciding what it proves.","Secure portals are preferable to open email where the business provides them."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Verify the client using the brokerage process.","Send the approved document checklist.","Use secure collection channels.","Record received date and document type.","Check readability, page completeness, and basic identity match.","Flag missing, inconsistent, or expired documents.","Route financial interpretation to the broker or credit specialist."]},{"type":"callout","title":"Stay inside the role","text":"Do not decide that income is acceptable, an expense is reasonable, a liability can be ignored, or identity evidence satisfies legal requirements unless the approved workflow specifically assigns that administrative check."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Downloading client documents to personal storage","Asking for unnecessary sensitive documents","Editing a client''s figures","Telling a client which expense to omit","Sending identity documents in open team chat"]},{"type":"scenario","title":"Practice scenario","text":"A payslip and bank statement show different employer names. Explain how you record the inconsistency without deciding whether the income is acceptable."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Collect securely.","Check completeness, not creditworthiness.","Preserve source documents.","Escalate inconsistencies."]}]'::jsonb,30,2,false,1,null,null,now(),now())
