insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='mortgage-broking-administration-australia'),'Fact Find and Research Support','Organize client information and lender facts without recommending.',2) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=2),'fact-find-data-entry-requirements-objectives-and-financial-position-support','Fact-Find Data Entry, Requirements, Objectives, and Financial Position Support','Responsible lending involves inquiries into a consumer''s requirements, objectives, and financial situation. A VA can organize data supplied by the consumer and broker, but should not turn data entry into assessment or advice.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support accurate fact-find data entry","Distinguish client statements from broker assessment","Avoid rewriting information to improve an application"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Responsible lending involves inquiries into a consumer''s requirements, objectives, and financial situation. A VA can organize data supplied by the consumer and broker, but should not turn data entry into assessment or advice."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Requirements and objectives need to reflect the consumer''s actual circumstances and goals.","Financial situation data can include income, expenses, assets, liabilities, dependants, and commitments.","Verification is a broker/licensee responsibility under the approved process.","Data provenance matters: who said it, when, and what document supports it.","Changes should be traceable."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Enter information from the approved source.","Preserve the client''s wording for objectives where required.","Record document/source references.","Flag conflicting figures.","Do not change expense or liability data to fit a lender policy.","Create broker-review tasks for judgment items.","Record the approved correction rather than overwriting history silently."]},{"type":"callout","title":"Stay inside the role","text":"Do not assess borrowing capacity, decide a loan is not unsuitable, determine whether expenses are acceptable, or coach a client to change answers."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Rounding expenses down to improve serviceability","Turning a broker note into a client statement","Deleting liabilities without evidence","Guessing missing dependants","Copying old fact-find data without reconfirmation"]},{"type":"scenario","title":"Practice scenario","text":"A client says their monthly living expenses are lower than last year''s fact find. Explain how you update the record while preserving source and broker review."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Data entry is not assessment.","Preserve source and history.","Flag contradictions.","Keep credit judgments with the broker."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=2),'product-and-lender-research-support-without-recommendation','Product and Lender Research Support Without Recommendation','Brokers compare lender policies, product features, fees, rates, eligibility, and turnaround times. A VA can gather current information, but choosing which product is in the client''s best interests is a regulated broker decision.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Research lender and product information carefully","Date-stamp policy information","Separate factual research from recommendation"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Brokers compare lender policies, product features, fees, rates, eligibility, and turnaround times. A VA can gather current information, but choosing which product is in the client''s best interests is a regulated broker decision."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Lender policies and rates can change frequently.","Broker access may depend on aggregator or lender panel.","A policy summary is not a recommendation.","Source date and official lender/aggregator reference matter.","The broker must consider the consumer''s circumstances and obligations when providing credit assistance."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Receive the broker''s research question.","Use approved lender/aggregator sources.","Record product name, policy fact, rate or feature, source, and checked date.","Avoid ranking products unless the broker requested a factual comparison format.","Flag ambiguous or conflicting policy information.","Hand the research to the broker for assessment."]},{"type":"callout","title":"Stay inside the role","text":"Do not tell the consumer which lender, rate, product, fixed/variable structure, offset, loan term, or feature is best for them."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using an old broker forum post as current policy","Calling the cheapest rate the best option","Ignoring lender panel restrictions","Failing to date-stamp research","Sending comparison conclusions directly to the consumer"]},{"type":"scenario","title":"Practice scenario","text":"Two lenders have different rates and policy rules. Prepare the factual comparison fields you would give the broker without naming a winner."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use current sources.","Separate facts from recommendation.","Date-stamp lender policy.","Broker owns best-interests judgment."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='mortgage-broking-administration-australia'),'Application and Approval Tracking','Package files and track lender conditions precisely.',3) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=3),'application-packaging-submission-and-lender-conditions','Application Packaging, Submission, and Lender Conditions','Once the broker decides to proceed, clean application packaging can reduce delays. The VA may organize approved data and documents, lodge through the brokerage workflow if authorized, and track lender requests without making credit representations beyond approved information.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Prepare complete application packs","Track submission and conditions","Avoid altering evidence to satisfy lender requirements"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Once the broker decides to proceed, clean application packaging can reduce delays. The VA may organize approved data and documents, lodge through the brokerage workflow if authorized, and track lender requests without making credit representations beyond approved information."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Application fields should match approved fact-find and documents.","Submission authority and system access should follow licensee policy.","Lender conditions may request additional evidence or clarification.","Valuations, credit decisions, and policy exceptions belong to lender/broker processes.","Every change should have a source."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use the broker-approved application checklist.","Check required documents and versions.","Confirm key data matches the approved fact find.","Prepare or submit only within assigned authority.","Record submission date and reference.","Track lender conditions and outstanding documents.","Route credit questions or policy exceptions to broker.","Maintain status in CRM."]},{"type":"callout","title":"Stay inside the role","text":"Do not alter income, expenses, liabilities, employment, purpose, property, deposit, or other facts to make the application fit lender policy."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Submitting an incomplete pack","Using outdated payslips without checking requirements","Changing a field after broker review with no trace","Answering lender policy questions from guesswork","Treating pre-approval as unconditional approval"]},{"type":"scenario","title":"Practice scenario","text":"A lender asks for clarification about a liability that is missing from the application but appears on a bank statement. Explain the admin response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Package from approved evidence.","Track conditions.","Never alter facts to fit policy.","Keep broker review visible."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=3),'valuations-conditional-approval-documents-and-pre-settlement-tracking','Valuations, Conditional Approval, Documents, and Pre-Settlement Tracking','Mortgage files can move through valuation, conditional approval, outstanding conditions, formal approval, loan documents, and settlement. Status labels matter because clients can make poor decisions if the team overstates certainty.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track post-submission milestones","Use precise approval language","Coordinate documents and deadlines"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Mortgage files can move through valuation, conditional approval, outstanding conditions, formal approval, loan documents, and settlement. Status labels matter because clients can make poor decisions if the team overstates certainty."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Valuation is one input, not a loan approval.","Conditional approval means conditions remain.","Formal or unconditional approval terminology should follow broker/lender wording.","Loan documents need controlled delivery and completion tracking.","Settlement involves lender, broker, conveyancer or solicitor, client, and other parties."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Record lender status exactly as received.","Create conditions checklist.","Track valuations and requested documents.","Use approved client-update templates.","Do not describe a conditional status as final.","Track loan documents sent, signed, returned, and accepted.","Maintain settlement date and outstanding items.","Escalate delays or changed conditions."]},{"type":"callout","title":"Stay inside the role","text":"Do not interpret loan documents, tell a client it is safe to exchange contracts or make commitments, or guarantee settlement. Route legal and credit decisions to the broker and relevant professionals."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling conditional approval ''approved''","Promising settlement date before lender confirmation","Explaining contract clauses","Losing track of outstanding conditions","Failing to update CRM after lender status changes"]},{"type":"scenario","title":"Practice scenario","text":"A client asks whether they can pay a non-refundable deposit because the lender has given conditional approval. Explain the safe VA response and broker/legal handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use exact lender status.","Track every condition.","Avoid guarantees.","Keep legal and credit advice with professionals."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='mortgage-broking-administration-australia'),'Settlement and Simulation','Close files cleanly and apply the full admin workflow.',4) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=4),'settlement-post-settlement-crm-and-referral-administration','Settlement, Post-Settlement, CRM, and Referral Administration','The file does not end when approval arrives. Settlement coordination, post-settlement records, client follow-up, commission/admin tracking, annual reviews, and referrals need clean systems.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Coordinate settlement administration","Close files with complete records","Create compliant follow-up and referral workflows"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"The file does not end when approval arrives. Settlement coordination, post-settlement records, client follow-up, commission/admin tracking, annual reviews, and referrals need clean systems."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Settlement status should come from confirmed parties.","Client records should preserve required compliance and application documents.","Post-settlement communication should avoid unsolicited product advice.","Referral partners and commissions may have disclosure/compliance rules.","Review reminders should not be treated as automatic product recommendations."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Track settlement date and confirmed completion.","Update CRM status.","Store final approved file documents.","Complete internal closeout checklist.","Trigger approved client thank-you or review process.","Record referral source accurately.","Create future review task using brokerage policy.","Keep unresolved commission or document exceptions visible."]},{"type":"callout","title":"Stay inside the role","text":"Do not tell a settled client to refinance, switch products, or take additional credit as an administrative follow-up. Product advice belongs to an authorized broker process."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Closing before settlement confirmation","Deleting application evidence","Sending product pitches from a generic template","Misreporting referral source","Ignoring unresolved lender or commission records"]},{"type":"scenario","title":"Practice scenario","text":"Six months after settlement, an automated campaign suggests refinancing. Explain why the VA should follow the broker''s approved review process instead of presenting a recommendation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Confirm settlement.","Preserve records.","Use approved follow-up.","Keep credit advice with brokers."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='mortgage-broking-administration-australia') and position=4),'mortgage-broking-administration-australia-composite-simulation','Mortgage Broking Administration Australia Composite Simulation','This simulation tests whether you can support a mortgage-broking file from enquiry to settlement without crossing into credit assistance or advice.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run a mixed mortgage-broking admin queue","Protect sensitive financial information","Produce a broker-ready compliance-aware handoff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests whether you can support a mortgage-broking file from enquiry to settlement without crossing into credit assistance or advice."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Licensing boundaries","Document intake","Fact-find data","Lender research","Application packaging","Conditions","Settlement","Recordkeeping"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Resolve routine document and CRM tasks.","Flag inconsistencies for broker review.","Prepare a factual lender-policy comparison.","Package an application without changing client facts.","Track lender conditions and settlement tasks.","Produce an end-of-day broker handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not recommend a lender or product, assess suitability, determine borrowing capacity, interpret credit-law compliance, change client facts, or present yourself as an authorized mortgage broker."},{"type":"callout","title":"Keep this current","text":"Australian credit law, lender policies, responsible-lending guidance, disclosure obligations, product policy, and settlement processes can change. Verify current ASIC guidance, lender policy, aggregator or licensee procedures, and the broker''s approved compliance process before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Giving product advice in admin messages","Changing expenses to improve serviceability","Calling conditional approval final","Using old lender policy","Storing client financial data insecurely"]},{"type":"scenario","title":"Practice scenario","text":"A fictional broker file includes missing income documents, inconsistent expenses, a client asking which lender is best, two policy options, a conditional approval with outstanding items, and a settlement deadline. Build the safe admin workflow and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Broker owns credit assistance.","Use current evidence.","Protect client data.","Keep statuses precise and records complete."]}]'::jsonb,30,2,false,1,null,null,now(),now())
