values ((select id from public.training_courses where slug='mortgage-broking-administration-australia'),null,'Mortgage Broking Administration Australia Final Work Simulation','Complete the mortgage-broking administration simulation covering privacy-safe document intake, fact-find data entry, lender research support, application packaging, lender conditions, settlement tracking, recordkeeping, and broker handoff. The learner must not provide credit assistance, product recommendations, borrowing-capacity judgments, or financial advice.','practical',null,1,false,now(),now());
